quests[32477] = { id = 32477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Player is Back in Time" }
quests[32485] = { id = 32485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering the Defenses", description = "This island is a dangerous place, {name}. We have to worry about attacks from the Zandalari, mogu, saurok, and worst of all the Sunreavers.\n\nI had perimeter wards placed on the outskirts of our camp for additional protection. In their current state they will only injure an attacker, but I'm done with warnings!\n\nWith your help we can super-charge the wards into a more deadly defense system.", completion = "Excellent work, {name}. Those perimeter wards should keep out all manner of filth.\n\nWith Violet Rise protected we can focus on more pressing matters.", objectives = "Empower 6 Kirin Tor Perimeter Wards around Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32489] = { id = 32489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in the Undercity.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", progress = "This should be fairly simple. Just smush them.", completion = "Every little bit helps.", objectives = "Crush 75 Ihgaluk Roaches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32491] = { id = 32491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", completion = "Left standing, those piles of discarded food are the perfect breeding ground for disease.\n\nWere I still in the disease-spreading business, I'd consider using them myself.", objectives = "Destroy 3 Fetid Meat Piles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32492] = { id = 32492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy Cauldrons" }
quests[32493] = { id = 32493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They All Fall Down", description = "The Zandalari do not tolerate weakness in their ranks, {class}.\n\nThose that are deemed weak are often sacrificed in barbaric ceremonies. The victims' spirits are captured and entombed within the sentries you see guarding the grounds.\n\nI wish to study their essence. For this I will need your help.\n\nTake this resonance crystal and siphon the spirits from the sentry corpses.\n\n Do not allow them to escape!", progress = "Have you completed your task, {class}?", completion = "Excellent work, {class}! This will aid my studies greatly, as well as advance our cause here.", objectives = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari Spirits trapped within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32494] = { id = 32494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Play", description = "The Zandalari have found a way to infuse items of great power with the essence of their loa. These items are often passed from one generation to another, each recipient adding to the item's power.\n\nTwo such items exist here. To be specific, two masks, worn by two brothers.\n\nSpiritbinder Tu'chek and Arcanital Ra'kul must be stopped and their masks destroyed.\n\nKill them and return their masks to me. I will make sure the masks are disposed of.", progress = "Do you have the masks?", completion = "Getting these masks was no easy task, {class}. I am grateful for your service.", objectives = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32495] = { id = 32495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bone, the mogu bring captives to a general named Kaida the Bloodletter.\n\nI will spare you the details, but he thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", progress = "The mogu are capable of unimaginable cruelty.", completion = "I am glad to hear that this piece of filth is slain. You have done us all a great favor, {name}.", objectives = "Kill Kaida the Bloodletter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32496] = { id = 32496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", objectives = "Desecrate the Horde's Vale of Eternal Blossoms bonfire!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32497] = { id = 32497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Dread Wastes flame.", objectives = "Honor the Midsummer Bonfire in Dread Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32498] = { id = 32498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Jade Forest flame.", objectives = "Honor the Midsummer Bonfire in Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32499] = { id = 32499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Krasarang Wilds flame.", objectives = "Honor the Midsummer Bonfire in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
