quests[32503] = { id = 32503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", objectives = "Desecrate the Alliance's Vale of Eternal Blossoms bonfire!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32504] = { id = 32504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Secrets of Stormwind", description = "Send undercover forces into the heart of enemy territory in an effort to learn of their plans." }
quests[32505] = { id = 32505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbled Chamberlain", description = "You there! Assist me.\n\nIn life I was the Royal Chamberlain for his majesty, the Thunder King. For my dedication, I was condemned to this stone form, forever forced to watch over a portion of his wealth.\n\nSomeone has desecrated my glorious body and sent pieces of it across the island. The thought of spending an eternity as nothing more than a head depresses me.\n\nSearch the island, recover these pieces and I shall grant you one of his majesty's treasures.", progress = "I require ALL of my pieces. If so much as a pebble is missing, I shall consider forfeiting our agreement.", completion = "Ah! To feel whole again! You have my gratitude, servant. Take this stone and use it wisely. Should you encounter his majesty the Thunder King in your travels, do not tell him where you received it, or you will be standing in a statue next to me for the remainder of eternity.", objectives = "Recover the Shoulder, Head, Staff, Hair and Torso of the Chamberlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32506] = { id = 32506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", progress = "A great gloom looms over this island...", completion = "Wonderful! I'll pass him off to our caretaker. Thank you.", objectives = "Recover a Wild Ptrerrorwing Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32507] = { id = 32507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Sunreavers behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", objectives = "Go to Ihgaluk Crag and slay a Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32508] = { id = 32508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Island" }
quests[32509] = { id = 32509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", objectives = "Honor the Vale of Eternal Blossoms flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32510] = { id = 32510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", objectives = "Honor the Vale of Eternal Blossoms flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32516] = { id = 32516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nTo the south, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter.\n\nI will spare you the details, but he thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", objectives = "Kill Kaida the Bloodletter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32517] = { id = 32517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", progress = "It is a mystery how the mogu can imbue life into inanimate stone, but with enough study, we, too, may one day be able to understand that power.", completion = "A good defense is just as effective as a strong offense. One less enemy to worry about.\n\nWell done.", objectives = "Stop the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32518] = { id = 32518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[32519] = { id = 32519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[32520] = { id = 32520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competing Magic", description = "My scouts have spotted a dangerous Zandalari just this side of Za'Tual. I need someone capable to see him dispatched. Are you up to the task?", completion = "Your skills are impressive indeed. Thank you for doing this for me, {name}.", objectives = "Kill Arcweaver Jor'guva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32521] = { id = 32521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "My scouts have spotted a Zandalari war party on the northern beach. I need someone capable to see him dispatched. Are you up to the task?", completion = "You have our gratitude, {name}.", objectives = "Kill Nurkala, the Zandalari War Leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32522] = { id = 32522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Threat", description = "My scouts have spotted a mogu leader under the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for me?", completion = "One less threat at our doorstep. Thank you, {name}.", objectives = "Kill Horgak the Enslaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32523] = { id = 32523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beast Pens", description = "We need to counter the beasts the Zandalari are using to strike at our camp. I have dispatched Scout Captain Elsia to the Beast Pens along with some war mages to provide cover.\n\nGo and find her east of here near the breaches in the wall and help her trim down the cavalry and siege beasts being levied against us.\n\nThey are masked, so look for the shimmers of their magical cloaking spells.", completion = "I'm glad you were the one Lor'themar sent. These beasts are more than we can handle on our own. Time to spook the livestock.", objectives = "Find Scout Captain Elsia at the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32524] = { id = 32524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beating of Troll Drums", description = "Do you hear that, {class}? The beating of war drums in the distance. The Zandalari are preparing for us.\n\nLet's not give them the luxury of time to organize their defenses. We need to push the attack now!\n\nReport to Scout Captain Elsia within Conqueror's Terrace. She will have further orders for you.", completion = "These Zandalari are even more dangerous than we anticipated.\n\nDo not make the mistake of underestimating them, for that may be the last mistake you make.", objectives = "Locate Scout Captain Elsia within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32525] = { id = 32525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Enemy", description = "The mogu at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", completion = "Their dead shall rise no more, thanks to you, {name}. Excellent work.", objectives = "Burn 8 Mummified Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32526] = { id = 32526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nAlliance or Horde, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", completion = "Thank you, {name}. You have lightened my heart of a heavy burden through your heroic actions.\n\nI will remember your efforts on this day.", objectives = "Save 6 Silver Covenant Scouts or Sunreaver Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32527] = { id = 32527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", completion = "Excellent. You have dealt the mogu a blow that they shall not easily forget.", objectives = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers, or Shan'ze Thundercallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32528] = { id = 32528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Crypts", description = "Every day, we uncover additional relics from the Court of Bones.\n\nRecently, we discovered this scroll amongst the gravestones in one of the deepest crypts.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", progress = "How did it go?", completion = "Ah yes, you've just confirmed my theory! Thank you, {class}.", objectives = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32529] = { id = 32529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Violet Rise.\n\nThere is no time to delay. You must stop their ritual at once.", progress = "Do not allow them to unleash the force of their weapon.", completion = "You continue to exceed my expectations, {class}. Well done.", objectives = "Stop the Shan'ze Thundercallers' ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32530] = { id = 32530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter.\n\nHe thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", progress = "The mogu are capable of unimaginable cruelty.", completion = "I am glad to hear that this piece of filth is slain. You have done us all a great favor, {name}.", objectives = "Kill Kaida the Bloodletter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32531] = { id = 32531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", progress = "It is a mystery how the mogu can imbue life into inanimate stone, but with enough study, we, too, may one day be able to understand that power.", completion = "A good defense is just as effective as a strong offense. One less enemy to worry about.\n\nWell done.", objectives = "Disrupt the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32532] = { id = 32532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", completion = "Wonderful work, {class}. This will help our offensive a great deal.", objectives = "Kill 15 Risen Ancestors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32533] = { id = 32533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Cold", description = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable.\n\nUnfortunately, we've received several reports of stone quilen statues coming to life without warning. These quilen are too dangerous to ignore.\n\nVenture into the Court of Bones and destroy any quilen statues that you can find.", completion = "I am glad to hear that you left the quilen in a thousand tiny pieces. They are little more than a nuisance to my work here on the island.", objectives = "Destroy 8 Grave Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32534] = { id = 32534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Horde takes full control of this island, we can look for more permanent solutions.", objectives = "Slay 10 Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32535] = { id = 32535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Alliance takes full control of this island, we can look for more permanent solutions.", completion = "One day, this island will belong to the Alliance. I can only hope that it will be free of saurok before then.\n\n<Modera sneers.>\n\nAt least they attack the Horde, too.", objectives = "Slay 10 Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32536] = { id = 32536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", progress = "Good luck, {name}.", completion = "<The archmage listens carefully to your report.>\n\nI understand. Thank you for your aid, {class}.", objectives = "Check in with Magister Yalis, Magister Lyanis, and Magistrix Sanal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32537] = { id = 32537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Silver Covenant property under my watch.", progress = "Hmph... saurok.\n\n<Modera spits.>", completion = "That's more like it.\n\nThank you, {class}.", objectives = "Recover the four stolen Silver Covenant Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32538] = { id = 32538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heinous Sacrifice", description = "Some of the strongest of the spiritbinders perform heinous rites to their wretched gods.\n\nWe've devised a method to destroy their altars, so the difficult task will be getting to each altar alive.\n\nVenture into the depths of Za'Tual and destroy their altars.", progress = "I realize what I ask you to do is dangerous, but it is necessary.", completion = "{class}, the destruction of those altars will force the trolls to halt their most heinous of sacrifices. You have the thanks of everyone here.", objectives = "Destroy the Zandalari's sacrificial altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32539] = { id = 32539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Offerings", description = "The Zandalari's spiritbinders perform dark sacrifices to appease their gods, killing our people in the process.\n\nDestroy any Zandalari offerings you can find in Za'Tual to help slow the pace of their dark sacrifices.", completion = "Without the offerings, they will need to collect more before their sacrifices can proceed. Thank you, {class}.", objectives = "Destroy 6 Zandalari Offerings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32540] = { id = 32540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of the Loa", description = "If you spend some time in Za'Tual, you will likely see one of their large tents emanating a pure form of evil.\n\nPlease, venture into the troll camp and put a stop to these unspeakable rituals.", completion = "Most who witness such rituals never return, and those that do tend to be shaken. You, {name}, seem little moved by your incredible deeds. I am impressed.", objectives = "Slay 2 Harbingers of the Loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32541] = { id = 32541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventing a Future Threat", description = "It pains me to think of the torture the poor skyscreamers  must endure as the trolls train them to become implements of war.\n\nThe hatchlings are quite fearful, and will fly away if you even get close them. Please, frighten some away before the Zandalari corrupt them.", completion = "Welcome back, {race}. The hatchlings you frightened will live a better life without their captors.", objectives = "Frighten 12 Hatchling Skyscreamers by running near them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32542] = { id = 32542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surgical Strike", description = "Zandalari spiritbinders perform sacrifices to their gods, the beastcallers bend innocent skyscreamers to their will, and the jaguar warriors venture closer to us by the day.\n\nDispose of these threats in Za'Tual, {race}, and watch the might of the trolls weaken.", completion = "With a few of their more threatening kin slain, perhaps the Zandalari will show reluctance next time they decide to trifle with us.", objectives = "Slay 3 Zandalari Spiritbinders, 3 Zandalari Beastcallers, and 3 Zandalari Jaguar Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32543] = { id = 32543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangers of Za'Tual", description = "The Zandalari are a formidable foe - more so than many foes we've encountered in the past. But you are a formidable foe as well, {name}.\n\nEnter Za'Tual to and show them the risks associated with opposing the likes of you.", completion = "{name}, your help against the Zandalari is appreciated. I realize it seems we cannot stem the tide, but your efforts make a difference.", objectives = "Slay 12 Trolls in Za'Tual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32544] = { id = 32544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrible Ptorment", description = "One of the trolls' skyscreamers in Za'Tual is undergoing a ritual of torture, its will being bent forever to serve its masters.\n\nKill those that inflict such torment on the creature and we can only hope that it will return to the skies.", progress = "Have you freed the creature?", completion = "I hope that creature has the intelligence necessary to know who saved it. It seems to me that it would be a dangerous foe if provoked.", objectives = "Free the Tormented Skyscreamer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32545] = { id = 32545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", progress = "The saurok value strength above all else. They only respond to strength.\n\nPeace with the saurok will require some amount of bloodshed. The question is, how much?", completion = "I know the true price of bloodshed. I know the cost of war.\n\nIt would be simpler to blindly massacre our attackers until they yield. But is it right?", objectives = "Slay a Skumblade Brute, a Skumblade Saur-Priest, and a Skumblade Seadragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32546] = { id = 32546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", progress = "Sorry in advance about the smell.", completion = "Well done, {name}. Looking at you, I'm suddenly quite proud of Dalaran's state-of-the-art plumbing system.", objectives = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32547] = { id = 32547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in Booty Bay.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", completion = "Every little bit helps.", objectives = "Crush 75 Ihgaluk Roaches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32548] = { id = 32548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", progress = "I know of many ways to spread disease, but this one is novel.", completion = "Left standing, those piles of discarded food are the perfect breeding ground for disease.\n\nWere I still in the disease-spreading business, I'd consider using them myself.", objectives = "Destroy 3 Fetid Meat Piles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32549] = { id = 32549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Kirin Tor behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", objectives = "Go to Ihgaluk Crag and slay a Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32550] = { id = 32550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in the Beast Pens before they can get their mounted monstrosities out into the open battlefield.", completion = "These trolls have been using dark magics to achieve their goals. No patience, no honor. You have done the world a good service in reducing their numbers today.", objectives = "Defeat 10 Zandalari trolls in the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32551] = { id = 32551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compy Stomp", description = "The raptors and saurid of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", completion = "We lost three good soldiers when we first arrived on this island. Killed in their sleep by compies that had snuck into their tent. Some nights I still hear the screams.", objectives = "Kill 5 Raptors and 10 Trained Saurid in the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32552] = { id = 32552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", progress = "I always believed the loa to be a simple troll superstition. These Zandalari are full of surprises.", completion = "Well done, champion. These beasts are strong enough. We don't need them infused with an angry spirit now do we?", objectives = "Defeat a Loa Speaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32553] = { id = 32553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn vs Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", progress = "So... did you decide the devilsaur or the direhorn?", completion = "Few things in this world and beyond are more entertaining than watching a rampaging ancient beast tearing through an enemy's settlement.\n\nIf times were not so dire I would consider selling tickets to such an event.", objectives = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32554] = { id = 32554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", completion = "Very interesting results. I am sure there is a mage somewhere that cares about the specifics. I, on the other hand, am just glad to hear the sound of trolls being assaulted by their own beasts.", objectives = "Find and use Saur Fetishes on 5 raptors, compies, skyscreamers or direhorns in the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32555] = { id = 32555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centuries in Sentries", description = "Sacrifices are common place in Zandalari society. There is however one oddity among these barbaric rituals; volunteers. They treat it as a great honor!\n\nThe weak still seek to contribute, even if that means giving their lives to be bound to the sentries you see walking around. Locked away in service to their people.\n\nTake this resonating crystal. Once destroyed, drain the sentry of its Zandalari inhabitant. Return the crystal to me when your task is complete.", progress = "How many spirits have you captured?", completion = "This is very interesting, {class}. The crystal hums with the rage of its captive inhabitants. Even after the passage of time their devotion has not decreased.\n\nI will need to study this further.", objectives = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari spirits trapped within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32556] = { id = 32556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The More You Know", description = "This whole area is littered with Zandalari artifacts. I would be lying if I said studying them didn't interest me. I am fascinated by the significance of these objects to their rituals.\n\nThe more we understand our enemies, the better prepared we are to defeat them.\n\nIf I am to study them, I will need to see them up close. Bring me as many artifacts as you can find.", progress = "What have you brought me, {class}?", completion = "These are excellent finds! Studying them will take time, but there is much to be gained in understanding the Zandalari.", objectives = "Retrieve 6 Ritual Artifacts from around Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32557] = { id = 32557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Enemy Hands", description = "Magic is a frightening opponent when wielded by an experienced caster. A blade however, is terrifying in even the most inexperienced hands.\n\nThe Zandalari have some impressive weapons, made even more deadly by the magic they are enhanced with. We should relieve them of this advantage.\n\nSteal as many of the weapons as you can find.", progress = "What did you find out there? Anything that can be of use?", completion = "Excellent work, {class}! These weapons are impressive. Now we have a few less things to worry about in the field of battle.", objectives = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32558] = { id = 32558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All In the Family", description = "Conqueror's Terrace is watched over by two brothers; Spiritbinder Tu'chek and Arcanital Rak'ul. They are powerful magic users and should not be underestimated.\n\nTheir power seems to stem from the ornate masks they wear; relics passed down from one generation to the next. Each owner imbuing it with their own magic before passing it on.\n\nWe must deal with the brothers and destroy their masks before they fall into the wrong hands.", progress = "Where are the masks?", completion = "It's a shame really that these masks must be destroyed. I would have liked to study this ancient magic, but it is better that they be destroyed than become the tools of the Horde.\n\nGood work, {class}.", objectives = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32559] = { id = 32559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Giants Fall", description = "The Zandalari worship the loa; animal spirits they often call to their aid. They may be trying to bind these spirits into a huge golem. The outcome would be disastrous.\n\nI've sent ahead a scout to gather more information, but I think this task may require your expertise.\n\nStop that ritual at all costs!", completion = "It's fortunate that you were able to intervene, {class}. Who knows what damage that golem would have caused had he not been stopped.", objectives = "Destroy Guardian Tak'u within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32560] = { id = 32560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep It Secret", description = "The Zandalari here are a threat to our campaign, {class}.\n\nTheir use of magic is an abomination. They mix the power of arcane with the darkness of shadow with little care to consequence.\n\nWe cannot afford for them to find their full strength here or for the Horde to learn of their twisted magic.\n\nTheir numbers must be thinned. I will leave this task to you.", completion = "Well done, {class}. The more Zandalari we destroy, the less chance their magic will fall into Horde hands.", objectives = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32561] = { id = 32561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competing Magic", description = "One of my scryers has identified a Zandalari leader near the central tower. He needs to be removed.\n\nWould you be willing to do this for me, {class}?", completion = "You're dependable, {name}. I like that.", objectives = "Kill Arcweaver Jor'guva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32562] = { id = 32562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Threat", description = "One of my scouts has returned with word of a mogu leader under the central tower. He needs to be removed.\n\nWould you be willing to do this for me, {class}?", completion = "I appreciate what you've done for us this day, {name}.", objectives = "Kill Horgak the Enslaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32563] = { id = 32563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp.\n\nAre you up for the task?", completion = "Thank you, {name}. That's a worry off my mind.", objectives = "Kill Nurkala, the Zandalari War Leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32564] = { id = 32564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalari on the Rise", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nCan you handle this one?", completion = "Yet again you prove yourself. We would be fortunate if all amongst us could aspire to your talents.", objectives = "Kill Arcweaver Jor'guva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32565] = { id = 32565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp.\n\nWould you be willing to handle this one?", completion = "Your skills are impressive. You have our gratitude.", objectives = "Kill Nurkala, the Zandalari War Leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32567] = { id = 32567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beast Pens", description = "I do not want to see another Zandalari beast rider breach our defenses!\n\nI have dispatched Scout Captain Daelin and some war mages to the Beast Pens northwest of here. Their mission is to infiltrate and harass the Zandalari siege and cavalry units. I want you to join them and lend your expertise.\n\nKeep an eye out for the tell tale shimmer of their magical cloaking spell.", completion = "Today, we hunt the hunters!", objectives = "Find Scout Captain Daelin at the Beast Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32568] = { id = 32568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time To Rest", description = "We have accomplished much since arriving here, but now is not the time to rest. Your efforts have helped us breach the upper level of the Thunder King's stronghold.\n\nNow, I call on you to continue our campaign. Report to Scout Captain Daelin within Conqueror's Terrace. He will have further orders for you.", completion = "The Zandalari here are not to be under-estimated, {class}. Powerful magic overwhelms this space.\n\nWe must be diligent in our efforts.", objectives = "Locate Scout Captain Daelin within Conqueror's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32569] = { id = 32569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trailing Light in the Dark", description = "There is some dark magic in the Diremoor that extinguishes even our magical illuminations, and so our scouts struggle to find their way.\n\nAs you pass through the swamp, relight any torches you find that our men might find their way. Perhaps they will help you find your way back as well.", objectives = "Relight 8 torches in the Diremoor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32570] = { id = 32570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Scout Reports" }
quests[32571] = { id = 32571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", progress = "A great gloom looms over this island...", completion = "Wonderful! I'll pass him off to our caretaker. Thank you.", objectives = "Recover a Wild Ptrerrorwing Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32572] = { id = 32572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", progress = "You are not done just yet, {class}.", completion = "Your efforts are appreciated, {class}.", objectives = "Kill 6 Animated Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32573] = { id = 32573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Vereesa wants them dead. I think you're the one to do it.", completion = "Well done, {class}. Thank you for the help.", objectives = "Kill 7 Shan'ze mogu in the Diremoor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32574] = { id = 32574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", completion = "You are not one to be trifled with. I am sure to have further use of your services.\n\nCome back to me in a day's time, {class}.", objectives = "Kill the Mighty Devilsaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32575] = { id = 32575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", completion = "When I give you a task, it gets handled.\n\nWell done, {class}.", objectives = "Destroy the Zandalari Colossus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32576] = { id = 32576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competing Magic", description = "One of the scryers has identified a Zandalari leader near the central tower. He needs to be removed.\n\nWould you be willing to handle this?", completion = "You're dependable, {name}. I like that.", objectives = "Kill Arcweaver Jor'guva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32577] = { id = 32577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Threat", description = "One of Vereesa's scouts has returned with word of a mogu leader under the central tower. He needs to be removed.\n\nWould you be willing to handle this?", completion = "I appreciate what you've done for us this day, {name}.", objectives = "Kill Horgak the Enslaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32578] = { id = 32578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Bones", description = "The scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. We need someone capable to see him dispatched. Are you up to the task?", progress = "Is it done?", completion = "It's good to have a man I can trust close at hand.", objectives = "Kill Zur'chaka the Bonecrafter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32579] = { id = 32579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competing Magic", description = "The scouts have spotted a dangerous Zandalari just this side of Za'Tual. We need someone capable to see him dispatched. Are you up to the task?", completion = "Your skills are impressive indeed. Thank you for doing this for me, {name}.", objectives = "Kill Arcweaver Jor'guva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32580] = { id = 32580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "We've received word of a Zandalari war party up the beach, north of our foothold. We need them hunted down and killed.\n\nAre you willing to do this thing for us, {class}?", progress = "Is it done?", completion = "You have our gratitude, {name}.", objectives = "Kill Nurkala, the Zandalari War Leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32581] = { id = 32581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposing Threat", description = "The scryers have spotted a mogu leader at the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for us?", progress = "Is it done?", completion = "One less threat at our doorstep. Thank you, {name}.", objectives = "Kill Horgak the Enslaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32582] = { id = 32582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", completion = "You're a good {class} to have around, that's for certain. Thank you.", objectives = "Kill Zur'chaka the Bonecrafter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32583] = { id = 32583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalari on the Rise", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nCan you handle this one?", completion = "Yet again you prove yourself. We would be fortunate if all amongst us could aspire to your talents.", objectives = "Kill Arcweaver Jor'guva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32584] = { id = 32584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp.\n\nAre you up for the task?", completion = "Thank you, {name}. That's a worry off my mind.", objectives = "Kill Nurkala, the Zandalari War Leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32585] = { id = 32585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Force", description = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp.\n\nWould you be willing to handle this one?", completion = "Your skills are impressive. You have our gratitude.", objectives = "Kill Nurkala, the Zandalari War Leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32586] = { id = 32586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Capacitor", description = "The mines north of here are critical to the mogu supply line. They are using giant lightning enchanted drills to extract the ore.\n\nIf you can disrupt the drills, they'll be destroyed, greatly slowing their ability to make weapons.\n\nOh, also, kill whoever is in charge, will you?", objectives = "Destroy the 3 lightning drills in the Ghost Iron Mines, and kill Metal Lord Mono-Han.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32587] = { id = 32587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", progress = "Well?", completion = "Good work. What you did today brings us one step closer to our ultimate goal.", objectives = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32588] = { id = 32588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Her Magic-ey Secret Service", description = "Under orders from Jaina herself, some of our agents attempted to sneak past mogu lines to find out what was going on in the mines.\n\nThey were captured, and are being subjected to who-knows-what kind of awful tortures.\n\nYou must free them and kill whoever captured them. We don't leave anyone behind!", objectives = "Rescue the three captured Kirin Tor agents within the Ghost Iron Mines, and kill Metal Lord Mono-Han.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32589] = { id = 32589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life Blood", description = "Scouts unearthed this strange construct hidden within the Lightning Vein Mine. A secret weapon of the Thunder King no doubt.\n\nPerhaps, there is a chance we can use this discovery to our benefit. If we can re-animate it, we can study it. More importantly, we can discover its weakness.\n\nGo to the Throne of Thunder and use this crystal to capture whatever essence animates these constructs.\n\nReturn to me when the task is complete.", progress = "Were you successful in our endeavor?", completion = "Excellent work, {class}. This is a dark magic indeed. We have much to learn here if we are to succeed.\n\nNow, we have only to hope that we can reanimate this creature.", objectives = "Use the Attuned Crystal to retrieve the Remnants of the Animus from the Dark Animus within the Throne of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32590] = { id = 32590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me Upstairs", description = "There's someone I'd like you to meet. Stormwind's own crown prince recently paid a visit to this humble inn. I've instructed my guards to defend him from any Horde aggression - I don't want to draw any undue attention to myself.\n\nHe and I have been discussing world events, such as the battle along the southern shores, his encounter with Garrosh, and the upcoming assault on the Thunder King.\n\nCome! Let's talk upstairs...", completion = "<Wrathion introduces you both.>\n\nPrince Anduin, this is {name}, possibly the most powerful {class} in Pandaria.\n\nOh - do you already know of each other? Interesting.", objectives = "Meet Wrathion upstairs on the second floor of the Tavern in the Mists in the Veiled Stair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32591] = { id = 32591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the First Empire", description = "For two thousand years the mogu ruled this entire land. So brutal was their regime that its name is never uttered aloud: Pandaren call it either the \"Old Kingdom\" or \"First Dynasty.\"\n\nThe Thunder King was its founder and first emperor. He amassed enormous power on what is now the Isle of Thunder.\n\nHis time has passed, {name}. We should claim some of his power for ourselves. Gather mogu relics for me from the Throne of Thunder, and amass some trillium - I have a plan!", progress = "What have you uncovered from the Throne of Thunder? Is the Thunder King's ferocious reputation warranted?", completion = "<Wrathion inspects the treasures you brought him.>\n\nWell done. The trillium will need additional refinement, of course, but these samples are pure.\n\nI will need to study these artifacts for a time but I believe I can use the knowledge contained here to craft something of great value to us both.", objectives = "Collect 20 Secrets of the Empire and 40 Trillium Bars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32592] = { id = 32592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Need a Champion", description = "You are a superb representative of your people, {race}. But I need someone special. I have big plans. And to enact them I will need a champion to carry my flame to the four corners of the world.\n\nAre you the one?\n\nProve it to me on the Isle of Thunder! Lay waste to any mogu, Zandalari, or saurok that you find. Impress me!", completion = "My Shado-Pan associates have spoken highly of your deeds. You have earned quite the name for yourself here in Pandaria!\n\nIt is settled. When the materials are ready, you will be my champion. You will be my instrument, my standard-bearer, my voice of change across this world.\n\nWe will do marvelous things together.", objectives = "Earn Exalted Reputation with the Black Prince by defeating mogu, Zandalari, and saurok enemies on the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32593] = { id = 32593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunder Forge", description = "Everything is prepared, {name}, and I have selected you to be my champion.\n\nNext, we must infiltrate the legendary Thunder Forge of Lei Shen himself! You and your faction will need to advance forward until the Thunder Forge is exposed, if it isn't already.\n\nOnce you have infiltrated the forge, meet me there. Be ready for a fight!", completion = "Behold! The Lightning Lance! A conduit that can channel and control the very same power that the Thunder King used to found an empire.\n\nIt is dormant... but you're about to change that. If you're worthy.", objectives = "Progress through the Isle of Thunder until you unlock the Thunder Forge. Meet Wrathion outside the Thunder Forge and complete his task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32594] = { id = 32594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Storm Lord", description = "Our next objective is to temper this weapon with the blood of a demigod, one imbued with the Thunder King's powers.\n\nMy agents tell me that the mogu named Shan Bu is creating just such a creature, intended to guard the Thunder King's citadel.\n\nOnce your faction has fought your way to the front gates, attack Storm Lord Nalak and thrust this lance into his side. The creature will do everything in his power to stop you - stay alive long enough to siphon out the power of the Storm Lord!", progress = "What of Storm Lord Nalak? And the lance? Details!", completion = "You've done it! The lance seethes with power and potential!\n\nOh my friend, you have earned a great reward...", objectives = "Progress through the Isle of Thunder until you unlock the final courtyard. Obtain a Tempered Lightning Lance by thrusting the lance into Storm Lord Nalak and surviving long enough to siphon his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32595] = { id = 32595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Heaven", description = "Do you recall Mason's Folly, the hilltop east of here where you and I met before?\n\nI'm going to use the Lightning Lance to create something special, and I certainly can't do it in here.\n\nMeet me atop Mason's Folly so that we may celebrate our victories together!", completion = "The Crown of Heaven! Use this to augment any piece of headgear.\n\nIt will also act as a third eye - I will be able to follow your progress as we embark on the next stage of our journey.", objectives = "Meet Wrathion atop Mason's Folly in the Veiled Stair and collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32596] = { id = 32596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of the Titans", description = "I'm beginning to see the bigger picture, now, and how the mogu relate to the Titans. But every answer brings with it more questions!\n\nThe only way to put this puzzle together is to find every scrap of Titan information we can scavenge from the Thunder King's palace. Destroy the Thunder King and his minions and collect as many Titan runestones as you can find!", progress = "What have you discovered so far?\n\nWe need to gather all the information we can!", completion = "Thanks to your work, {name}, we've reconstructed an ancient narrative. The mogu were once creatures of stone, enacting the will of the Titans. But then their master fell silent, and they succumbed to the curse of the flesh. Eventually Lei Shen came along, imprisoned the keeper Ra, and took his power. Ah, what an empire he built!\n\nArmed with this knowledge, it's time to act...", objectives = "Collect 12 Titan Runestones from raid bosses in the Halls of Flesh-Shaping and the Pinnacle of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32597] = { id = 32597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Thunder King", description = "The Thunder King. Dead for twelve thousand years, only to be brought back by Zandalari voice. No doubt Titan power preserved his vile corpse.\n\nTitan power that's mine by right.\n\n{name}! Bring me the heart of the Thunder King. I will have it, and once it is mine, none will ever be able to resurrect him again.\n\nBring it to me, {class}. Bring me his cold, dead heart!", progress = "The Thunder King! What has become of him?", completion = "<Wrathion squeezes the black heart in his hand, his eyes burning brightly.>\n\nYou did it... you did it! The black heart of the Thunder King!", objectives = "Slay the Thunder King in the Halls of Thunder and collect the Heart of the Thunder King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32598] = { id = 32598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Reckoning", description = "The Thunder King is dead, and his instruments of oppression are being picked over by the Alliance and Horde for their own ends.\n\nWe come now to the climax of the pandaren campaign. Hellscream's machinations have brought the Alliance down on his head - but even more importantly, he's fractured the unity of the Horde. As the Pandaren say: \"The Wok is Hot.\" Something is about to give, and all of our work comes down to this.\n\nI need time to plan. See me as soon as your faction is ready to make its move!", sourceObjective = "Speak with Wrathion upstairs at the Tavern in the Mists in the Veiled Stair.", sourceObjectiveStatus = "unverified-source-field" }
quests[32599] = { id = 32599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing A Future", description = "It is rumored that the Thunder King's power comes directly from a hidden source within his palace.\n\nEven when he is defeated a new tyrant, Garrosh perhaps, could still use this magic to a terrible end.\n\nThat is unless we make the first move!\n\nTake my staff into the Pinnacle of Storms. Once Lei Shen has been defeated place my staff in the center of his dais.\n\nWe will drain the rest of his power and make sure it stays in our hands.", progress = "We will be unstoppable once Lei Shen's power has been fused with my staff.", completion = "You have just secured our advantage, {name}. Your work here will be remembered.\n\nGarrosh will be made to pay for his actions!", objectives = "Defeat the Thunder King within the Pinnacle of Storms and use the Staff of Antonidas to drain the remaining power from his dais.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32600] = { id = 32600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Prophecy", completion = "No wonder the Zandalari have come. They are in need of a new home, and I am sure their mogu allies have promised them much.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring The Zandalari Prophecy to Lorewalker Cho.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32601] = { id = 32601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumbles of Thunder", completion = "What we know of Lei Shen are dark legends that have been remembered over the vast span of time. I often wondered if these legends had exaggerated the power of Lei Shen. But your research would suggest they may have greatly underestimated the Thunder King. These are dark days indeed.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring the Rumbles of Thunder to Lorewalker Cho.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32602] = { id = 32602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gods and Monsters", completion = "Your research is most distressing. But it sheds light on a truth we have long sought: \"Where did the mogu come from? And why were they such tyrants?\"\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", objectives = "Bring the Gods and Monsters to Lorewalker Cho.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32603] = { id = 32603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Fable", description = "Have you ever read the great Pandaren book of fables?  Pandaren pass these stories on to their cubs - stories of the cricket and the hawk, or the slow-moving turtle - to teach them lessons that they will find useful in life. What few cubs know is that these creatures exist, here, in Pandaria! Though the stories of their travels are made up, they are powerful denizens of this world. Should you happen upon them in your travels, you may test the might of your pets against their storied statures.", completion = "You found them all? Amazing! So the stories ARE true! Perhaps you will write the next great Pandaren fable based on your own incredible journey!", objectives = "Defeat the Elite Battle Pets of the Pandaren fables.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32604] = { id = 32604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Fable Book I", description = "The stories of Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga will exist in this land, always. Do you wish to meet them in battle once more?", progress = "Do you return victorious?", completion = "I bow to you who continues to walk in the footfalls of the great Pandaren fables.", objectives = "Defeat Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32605] = { id = 32605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Horde lives.", progress = "As much as it pains me to say it: try not to kill them all. We need some alive if we want to turn them against the mogu.", completion = "Masterfully done, {class}.", objectives = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32606] = { id = 32606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Alliance lives.", completion = "Masterfully done, {class}.", objectives = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32607] = { id = 32607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extended Shore Leave", description = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort.\n\nSimply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault.\n\nNo captain. No repairs. No warship.", progress = "Each passing hour brings us closer to breaking the Thunder King.", completion = "Casualties are down significantly with that warship out of commission, and we continue to press the siege on Lei Shen.\n\nFantastic work out there today, hero.\n\nPlease, take this - you have earned it.", objectives = "Steal the Workshop Orders and slay the new captain of the Zandalari warship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32608] = { id = 32608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding the Vault", description = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same.\n\nOne artifact in particular, an amulet known as the Choker of Storms, could help us to understand his apparent mastery over lightning.\n\nBreak into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", progress = "The Thunder King's strength is legendary. We need every advantage we can get if we want to defeat him.", completion = "What's this? A necklace? What are you trying to- ahh, I see... A relic from the Thunder King's vault! Fascinating... Powerful, too.\n\nThe Kirin Tor will keep it safe. In return, please accept this.", objectives = "Steal the Choker of Storms from The Swollen Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32609] = { id = 32609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Chest Tracking Quest" }
quests[32610] = { id = 32610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Boss Tracking Quest" }
quests[32611] = { id = 32611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Drop Tracking Quest" }
quests[32613] = { id = 32613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giant Dinosaur Bone", progress = "What do you bring Ku'ma?", completion = "<Ku'ma shrugs.>" }
quests[32614] = { id = 32614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Giant Dinosaur Bones", progress = "Give them! Give them to me!", completion = "Bones bones bones bones bones..." }
quests[32615] = { id = 32615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many More Giant Dinosaur Bones", progress = "Who are you? Why have you returned? Hehehe...", completion = "Too many, not enough, no no...give them to Ku'ma..." }
quests[32616] = { id = 32616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Large Pile of Giant Dinosaur Bones", progress = "<Ku'ma cackles madly and gestures at you.>", completion = "Do you fear death? Hehe..." }
quests[32617] = { id = 32617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mountain of Giant Dinosaur Bones", progress = "<Ku'ma begins to dance around his hovel.>", completion = "<Ku'ma's jaw falls off at the sight of so many bones.>" }
quests[32618] = { id = 32618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Randal Hunter at the Eastvale Logging Camp in Elwynn Forest.  Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here!  Katie Hunter can be found here in camp.", objectives = "Find Randal Hunter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32621] = { id = 32621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Steel", description = "Your trained eyes can see that this metal ingot has some very strange properties. Perhaps there are clues to its nature somewhere around here?", completion = "While the language is incomprehensible, the diagrams in this book yield their knowledge to your skilled blacksmith's eye. It is clear that, by manipulating the properties of ghost iron, you can create a material of great power, perhaps powerful enough to recreate and increase the power of weapons long lost to the mists of time.", objectives = "Investigate the Thunder Forge to find the Secrets of Lightning Steel.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32622] = { id = 32622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intro Flight" }
quests[32626] = { id = 32626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loot Room Key Tracking Quest" }
quests[32627] = { id = 32627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charged Moganite", description = "We have been dispatching spies into the Sunreaver base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Sunreaver base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", completion = "Well done, champion. This artifact will be put to better use in our hands than in the hands of the Sunreavers.", objectives = "Recover a Charged Moganite and bring it to Warmage Yurias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32628] = { id = 32628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Mana Bombs", completion = "It pains me to resort to such weaponry, but the Sunreavers must be taught the price of their actions.", objectives = "Plant a Tactical Mana Bomb on a Sunreaver ship, the Scrying Crystals, and on the most inland bridge of Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32629] = { id = 32629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderwing Captured Tracking Quest" }
quests[32630] = { id = 32630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Engineer Jard's Journal", description = "What an unusual power source. Wonder how it works? And what it can be used to create?", sourceObjective = "Investigate the Thunder Forges to find the Secrets of Stabilized Lightning.", sourceObjectiveStatus = "unverified-source-field" }
quests[32631] = { id = 32631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Recognition", objectives = "Your presence on the battlefield cannot be ignored. I would like to give you something extra for your efforts, {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32632] = { id = 32632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Made for War", description = "Some things are built with multiple purposes in mind. Some things are built with the sole purpose of destruction.\n\nA massive construct called the Pyrestar Demolisher sits guarding Dawnseeker Promontory. Its purpose is solely to destroy. It must be dismantled.", completion = "Excellent work, {race}. The problem with constructs is they can always be rebuilt.\n\nI imagine it will not take the Sunreavers long to build a new death machine.", objectives = "Kill the Pyrestar Demolisher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32633] = { id = 32633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spellbound", description = "Grand Magister Rommath has something in his possession that I want.\n\nHe brought a very powerful tome with him. It would be better for our cause if it were no longer in Sunreaver hands.\n\nLocate Rommath's book of incantations and bring it to me.", progress = "Did you find the tome?", completion = "Ah yes! This is it. You've done well, {race}.", objectives = "Retrieve Rommath's Book of Incantations from Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32634] = { id = 32634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Down the Defenses", description = "Even the strongest defense can still have a weakness, {class}. We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible.\n\nScouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly.\n\nDisabling them would allow us to keep closer watch on their activities.", completion = "Excellent work, {race}! I was able to get a few of my scouts behind their lines before the perimeter wards were repaired.", objectives = "Destroy 6 Sunreaver Perimeter Wards around Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32635] = { id = 32635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough with the Bombs!", description = "The Sunreavers have planted tactical mana bombs around our camp. These must be dismantled before they are detonated.\n\nLook for them in areas of high importance such as our supplies. Make sure you find and disable them all. We cannot afford to lose any ground here.", completion = "I'm grateful for your efforts here, {name}. We would have lost so much had you not disarmed those bombs in time.", objectives = "Disarm the Tactical Mana Bombs at the Alliance Ships, the Construct Ritual, and the Supplies within Violet Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32636] = { id = 32636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captive Audience", description = "The Sunreavers will stoop to even the lowest levels to get what they want, {name}.\n\nI received reports earlier that several Kirin Tor have gone missing. I suspect the Sunreavers may have something to do with this.\n\nHopefully they have not been harmed, or my wrath will be swift and terrible. I trust you to bring them back in one piece, but please hurry.", completion = "You have saved many today, {name}. I cannot imagine the horror of being frozen and helpless among so many enemies.", objectives = "Free 5 Kirin Tor Captives near Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32637] = { id = 32637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overpowered", description = "The Sunreaver forces have grown more powerful recently. I suspect magic to be at play here, but I can't be certain.\n\nI think it would be wise to investigate their camp to see if you can find the source of this extra power.\n\nOnce you find it, use this crystal to overload and destroy it.", completion = "So they've constructed objects that infuse their forces with additional power? This will have to be watched closely.\n\nThank you for your efforts today.", objectives = "Destroy 7 Sunreaver Mana Collectors around Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32638] = { id = 32638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Scavengers", description = "Sometimes, even the smallest creatures can be the biggest threat.\n\nThe Sunreavers brought mana wyrms with them. Though small in size they have the ability to cripple our casters in combat. Many have learned the hard way not to underestimate them.\n\nThey must be dealt with and quickly.", completion = "You've made excellent progress today, {class}. Rest assured however, our work here is nowhere close to done.", objectives = "Kill 9 Sunreaver Mana Wyrms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32639] = { id = 32639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deconstruction", description = "Scouts are reporting a large number of constructs patrolling outside of Dawnseeker Promontory.\n\nIf left unchecked they will pose a considerable threat should the Sunreavers mount an attack.\n\nThe only answer is a preemptive strike. We'll destroy them before they can attack us!", completion = "Good work, {class}. As long as we keep the construct numbers in check, we will ensure our success here.", objectives = "Destroy 3 Sunreaver Constructs outside of Dawnseeker Promontory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32640] = { id = 32640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", progress = "Against these ancient enemies, there is no rescourse.  We strike first, and they do not strike at all.", completion = "Yours skills as a {class} are unquestionable. You've aided the cause greatly this day. You have my thanks.\n\nAnd now for that reward I promised you...", objectives = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder, and then defeat the powerful opponents that are summoned forth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32641] = { id = 32641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", progress = "Against these ancient enemies, there is no rescourse.  We strike first, and they do not strike at all.", completion = "Yours skills as a {class} are unquestionable. You've aided the cause greatly this day. You have my thanks.\n\nAnd now for that reward I promised you...", objectives = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder, and then defeat the powerful opponents that are summoned forth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32642] = { id = 32642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Dominance Offensive I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Horde I decided to pass this order your way.\n\nThe Dominance Offensive has requested an order of red blossom leeks.\n\nThe troops down there just can't seem to get enough of them!", objectives = "Plant 8 Red Blossom Leek Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32643] = { id = 32643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Dominance Offensive II", description = "Once your red blossom leeks are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your red blossom leeks will be a part of your faction's efforts in Pandaria!", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Red Blossom Leeks into the crate! A Dominance Offensive representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe Red Blossom Leek plants and provide 40 Red Blossom Leeks for the Dominance Offensive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32644] = { id = 32644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault on Shaol'mara", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", progress = "We must claim a better strategic position on the island itself.", completion = "Yes! You have done it, champion!\n\nNow, the Thunder King will taste the full force of the Kirin Tor!", objectives = "Complete the Assault on Shaol'mara. Speak to Jaina Proudmoore to begin the attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32645] = { id = 32645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Operation: Shieldwall I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Alliance I decided to pass this order your way.\n\nOperation: Shieldwall has requested a whole heap of witchberries.\n\nI can't be sure, but I think they have an idea to use them in some sort of weapon.", objectives = "Plant 8 Witchberry Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32646] = { id = 32646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Operation: Shieldwall II", description = "Once your witchberries are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your witchberries will be a part of your faction's efforts in Pandaria!", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Witchberries into the crate! An Operation: Shieldwall representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe Witchberry plants and provide 40 Witchberries for Operation: Shieldwall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32647] = { id = 32647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Golden Lotus I", description = "<Yoon kept this order request short.>\n\nThe Golden Lotus have requested a large number of white turnips.\n\nTheir request mentioned something about trouble-making sprites wreaking havoc on Mistfall Village. Apparently the sprites don't like turnips!", objectives = "Plant 8 White Turnip Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32648] = { id = 32648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Golden Lotus II", description = "Well, hopefully these crops will be suitable!\n\nOnce your white turnips are ready to be picked, you'll need only to package them for pick-up.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the White Turnips into the crate! A Golden Lotus representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe White Turnip plants and provide 40 White Turnips for the Golden Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32649] = { id = 32649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Shado-Pan I", description = "<Yoon's writing seems rushed. He must have been excited.>\n\nThe Shado-Pan want crops from you! What an honor indeed!\n\nA request came in this morning for green cabbages. Apparently, they make a rather tasty cabbage soup with them.\n\nOnly the finest will do for the Shado-Pan!", objectives = "Plant 8 Green Cabbage Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32650] = { id = 32650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Shado-Pan II", description = "Well, your work is done for the day! Now to wait for the harvest tomorrow.\n\nOnce your green cabbages are ready to be picked, you'll need only to package them for pick-up.\n\nOnly the finest cabbage will do for the Shado-Pan!", progress = "The crate sits empty awaiting your crops.", completion = "Gently place the Green Cabbages into the crate! A Shado-Pan representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe Green Cabbage plants and provide 40 Green Cabbages for the Shado-Pan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32651] = { id = 32651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intro Flight" }
quests[32652] = { id = 32652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Skies!", description = "We have a plan to halt the mogu's weaponmaking capabilities, and it involves the creature you recovered from the Zandalari.\n\nSpeak to me when you're ready to learn more.", progress = "It's time to begin your mission!", completion = "Incredible work. This presents us with a monumental opportunity.", objectives = "Gain access to the Lightning Vein Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32653] = { id = 32653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The August Celestials I", description = "<Yoon's familiar writing scrolls across the tattered paper.>\n\nThe trainees out at the Cradle of Chi-Ji are in need of striped melons. Apparently, they use them in their training exercises.\n\nA representative will be by tomorrow to collect whatever striped melons you can spare.", objectives = "Plant 8 Striped Melon Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32654] = { id = 32654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", progress = "Let's tear down this wall.", completion = "With your help, we're one giant step closer to our goal.", objectives = "Speak with Lady Jaina Proudmoore, then break into the lower city and secure it for the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32655] = { id = 32655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bold Idea", description = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army.\n\nIf we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure.\n\nI have a plan to do just that, and it won't take an entire army.", completion = "Well done. That warship won't be raining fire on us again any time soon.\n\nTaran Zhu has informed me that the Shado-Pan will keep vigil over Stormsea Landing, freeing up Kirin Tor resources to press the siege elsewhere. Taoshi will be there. I am sure she will be glad to work with you again.\n\nWe are all grateful for your contributions, {name}. Thank you.", objectives = "Infiltrate Stormsea Landing and open the courtyard gate from within. Speak with Taoshi to begin the mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32656] = { id = 32656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Shan Bu", description = "Lei Shen found a clutch of rare storm dragon eggs early in his campaign. One - known as Nalak - was particularly brutal and killed all of its handlers, so he took it for his own.\n\nNow, Shan Bu, one of Lei Shen's most loyal servants, works to resurrect the dragon.\n\nIt is time for us to strike against Shan Bu!\n\nSpeak to me when you are ready to launch the assault!", progress = "The time to defeat Shan Bu is now!", completion = "You've done it, {class}! Shan Bu is dead once and for all, and we've learned that Lor'themar may not be all that he seems.", objectives = "Defeat Shan Bu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32657] = { id = 32657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The August Celestials II", description = "Once your striped melons are ready to be picked, you'll need only to package them for pick-up.\n\nA trainee from the Cradle of Chi-Ji will be along shortly to collect their order.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Striped Melons into the crate! Now the August Celestials' order is ready to go!", objectives = "Harvest 8 Ripe Striped Melon plants and provide 40 Striped Melons for the August Celestials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32658] = { id = 32658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The Klaxxi I", description = "<Though Yoon's writing leaves something to be desired, it's nice to still have a little piece of him on the farm.>\n\nAn order came in this morning from the Klaxxi. Strangely enough they are requesting mogu pumpkins for some kind of research.\n\nI find it's best not to ask them too many questions...\n\nBest get started on their order. I'd hate to see what a bug of that size could do to your crops if you don't!", objectives = "Plant 8 Mogu Pumpkin Seeds on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32659] = { id = 32659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: The Klaxxi II", description = "Once your mogu pumpkins are ready to be picked, you'll need only to package them for pick-up.\n\nI wouldn't dilly-dally if I were you. The Klaxxi aren't known for their patience!", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Mogu Pumpkins into the crate! A Klaxxi representative will be along shortly for pick-up.", objectives = "Harvest 8 Ripe Mogu Pumpkin plants and provide 40 Mogu Pumpkins for the Klaxxi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32661] = { id = 32661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Aalun at the entrance to the Exodar on Azuremyst Isle.  Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! Torallius is right over there.", objectives = "Find Aalun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32662] = { id = 32662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Ultham at the Amberstill Ranch in Dun Morogh, along the road east out of Ironforge.  Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! Veron Amberstill is standing just outside the gates to the Ranch.", objectives = "Find Ultham Ironhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32663] = { id = 32663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Binjy Featherwhistle at the Steelgrill's Depot in Dun Morogh.  Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! Milli's right over there!", objectives = "Find Binjy Featherwhistle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32664] = { id = 32664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Jartsam at the Cenarion Enclave in Darnassus.  Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Lelanai right here.", objectives = "Find Jartsam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32665] = { id = 32665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Mei Lin north of the Dwarven District in Stormwind.  Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Old Whitenose here.", objectives = "Find Mei Lin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32666] = { id = 32666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Warlock - Green Fire" }
quests[32667] = { id = 32667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Softpaws in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Turtlemaster Odai here.", objectives = "Find Softpaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32668] = { id = 32668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Perascamin at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Winaestra just outside.", objectives = "Find Perascamin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32669] = { id = 32669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kildar in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Ogunaro over there.", objectives = "Find Kildar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32670] = { id = 32670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kar Stormsinger in Mulgore's Bloodhoof Village. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Harb Clawhoof over there.", objectives = "Find Kar Stormsinger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32671] = { id = 32671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Xar'Ti at Sen'jin Village in southern Durotar. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Zjolnir over there.", objectives = "Find Xar'Ti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32672] = { id = 32672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Velma Warnam at Brill in Tirisfal Glades. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Zachariah Post here.", objectives = "Find Velma Warnam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32673] = { id = 32673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Revi Ramrod in Orgrimmar's Valley of Spirits. Don't forget to buy your mount while you are there!", completion = "Don't forget to buy your mount while you are here! You can buy one from Kall Worthaton over there.", objectives = "Find Revi Ramrod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32674] = { id = 32674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Believe You Can Fly", description = "The skies call out to you! It's time to learn to fly!\n\nVisit the flying trainer, Maztha, at the Skyway in Orgrimmar.\n\nAnd don't forget to buy a flying mount!", completion = "Ah, good to see you. You look like you are ready to take to the skies!\n\nRemember, you can buy a flying mount from Drakma, just behind me.", objectives = "Find Maztha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32675] = { id = 32675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Believe You Can Fly", description = "The skies call out to you! It's time to learn to fly!\n\nVisit the flying trainer, Bralla Cloudwing, at the Gryphon Roost in Stormwind.\n\nAnd don't forget to buy a flying mount!", completion = "Ah, good to see you. You look like you are ready to take to the skies!\n\nRemember, you can buy a flying mount from Tannec Stonebeak over there.", objectives = "Find Bralla Cloudwing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32676] = { id = 32676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extended Shore Leave", description = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort.\n\nSimply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault.\n\nNo captain. No repairs. No warship.", progress = "Lei Shen will fall to our onslaught, and my people will find glory in his ruin.", completion = "This so-called \"Thunder King\" is surrounded and cut off from his allies. No tyrant is strong enough to stand alone.\n\nYour efforts have not gone unnoticed. Take this, with my thanks.", objectives = "Steal the Workshop Orders and slay the new captain of the Zandalari warship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32677] = { id = 32677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding the Vault", description = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same.\n\nOne artifact in particular, an amulet known as the Choker of Storms, could help us to understand his apparent mastery over lightning.\n\nBreak into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", progress = "You have good news, I hope.", completion = "Ah, I know a powerful artifact when I see one. You were wise to bring this here. I will see that Aethas examines it right away - perhaps we can put it to work in our favor.\n\nIn the meantime, take this in trade.", objectives = "Steal the Choker of Storms from The Swollen Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32678] = { id = 32678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Calls", description = "The time to attack the Thunder King has come!\n\nA small group of Sunreavers awaits you near the Shado-Pan Garrison in Townlong Steppes.\n\nReport to Scout Captain Elsia for further instructions.", completion = "We must move quickly, {name}! The others have gone ahead of us, but I will brief you in the flight over.", objectives = "Report to Scout Captain Elsia at the Shado-Pan Garrison in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32679] = { id = 32679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Calls", description = "The time to attack the Thunder King has come!\n\nA small group of Kirin Tor awaits you near the Shado-Pan Garrison in Townlong Steppes.\n\nReport to Vereesa Windrunner for further instructions.", completion = "We must move quickly, {name}! The others have gone ahead of us, but I will brief you in the flight over.", objectives = "Report to Vereesa Windrunner at the Shado-Pan Garrison in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32680] = { id = 32680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives Jaina and the Kirin Tor more of a hold on the Isle.\n\nLor'themar awaits us. Speak to me when you are ready to depart. I will escort you there myself.", progress = "This isle holds many secrets my friend.", completion = "You have arrived just in time, {race}. It is crucial we gain control of these shores before the Kirin Tor.\n\nThere is much to explain.", objectives = "Travel with Scout Captain Elsia to the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32681] = { id = 32681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives the Sunreavers more of a hold on the Isle.\n\nLady Jaina Proudmoore awaits us. We should not make her wait any longer.\n\nSpeak to me when you are ready to depart. I will escort you there myself.", progress = "The key to our safety lies here, {name}. I feel it to my core that we are meant to be here.", completion = "You have arrived just in time, {name}. This land needs to be controlled by the Kirin Tor for everyone's safety. This will not be an easy task.", objectives = "Travel with Vereesa Windrunner to the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32682] = { id = 32682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inherit the Earth", description = "As you know, {name}, I'm getting along in my years. One can't stay a spry young pandaren forever, you know.\n\nI'm looking for someone to take over my duties here at the Tillers Union, and I can't think of a better person than Farmer Yoon.\n\nHe's got a good deal to learn, but he's got a good head on his shoulders and most importantly, a generous heart.\n\nDo you think he'd be interested?", completion = "Why I just knew you could convince him, {name}. You've set my heart at ease, knowing the Tillers will be in good hands.", objectives = "Speak to Farmer Yoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32683] = { id = 32683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So You Want to Be a Blacksmith...", description = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key.", progress = "How are your studies coming along?", completion = "Well done. You are ready to become a zen master blacksmith.", objectives = "Create a Ghostly Skeleton Key by attaining at least 500 skill in blacksmithing. If you wish to train through pandaren materials, a training project appropriate to your skill level can be learned from Cullen Hammerbrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32684] = { id = 32684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Want Fish?", description = "Are you looking for golden carp? or some other Pandaren fish? I'm no fisherman myself, but there is a fellow by the river who has been teaching the folks traveling through here. If you go speak with him, he will likely give you some fish, as well as teach you how to fish.", completion = "Ah!  Have you come to learn how to fish? You're talking to the right person. First, here - have some fish!", objectives = "Speak with Ben of the Booming Voice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32685] = { id = 32685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Fishing Pole Necessary!", description = "You don't even need to equip a fishing pole in Pandaria!\n\nThe waters are TEEMING with fish. You'll catch one pretty much every time, as long as you are paying attention. Give it a go!", progress = "Catch 5 Golden Carp. Try it without a fishing pole!", completion = "Let me see...  Yes, these are nice. Good job! Here, have some more.", objectives = "Catch 5 Golden Carp. Try it without a fishing pole!\n\nTo fish, simply click the Fishing icon on the Profession pane. Pay attention to the bobber, click on it when it bobs and you will have your fish!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32686] = { id = 32686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Banner of the Mantid Empire", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", progress = "Remove the clutter and put the artifact on display.", completion = "This will aid lorewalkers and archaeologists in understanding the history of Pandaria.", objectives = "Put the artifact on display.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
