quests[32705] = { id = 32705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest Reward Summary: PvE Stage 5" }
quests[32706] = { id = 32706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", completion = "Welcome, {name}.", objectives = "Speak to Taran Zhu in Bleak Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32707] = { id = 32707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Isle of Thunder", description = "I do have one thing I would ask of you, {class}.\n\nWe've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals.\n\nIf you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.", progress = "Have you found the stones I spoke of?", completion = "Perfect. I will show you how to use these stones, and then you can spring the ambush.", objectives = "Recover 3 Shan'ze Ritual Stones. These stones are very rare, and may take some time to gather.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32708] = { id = 32708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Trap", description = "Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies.\n\nYou will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants.\n\nWhen your enemy shows itself, show no mercy.", progress = "Did the ambush succeed?", completion = "Very impressive.\n\nShould you find more stones, you should continue this ruse. It is sure to be quite some time before they catch on to our ploy.", objectives = "Use 3 Shan'ze Ritual Stones to beckon a Champion of the Thunder King, and then kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32709] = { id = 32709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", completion = "Welcome, {name}.", objectives = "Speak to Taran Zhu in Bleak Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32710] = { id = 32710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Foul is Afoot", description = "You notice a stronger-than-usual smell permeating from ahead. Your stomach lurches as the thick smell fills your nostrils.\n\nYou recognize this smell, it's saurok. Rotting, discarded saurok flesh infused with the foul waste of the sewer.", objectives = "Seek and destroy Flesh'rok the Diseased.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32711] = { id = 32711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agony and Anima", description = "You notice the initials A.K. skillfully and with calligraphic precision engraved onto the side of the Animus.\n\nBefore you stands Archritualist Kelada, the shaper of the Animus. By command of the Thunder King, Kelada worked tirelessly to craft the perfect vessel to harness the great power of the anima. Something functional, magnificent, sentient, but most importantly... something deadly.\n\nHe must be stopped before his next imagination is brought to life by the Thunder King.", objectives = "Slay Archritualist Kelada.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32712] = { id = 32712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zao'cho the Wicked", description = "Electricity hums in the distance, tickling your ears and sending impulses down your spine. Your fingers go numb, and  your heart races as you approach the door ahead.\n\nZao'cho stands arrogantly atop the steps ahead, weaving lightning between his fingers and smirking at you with demented glee.", objectives = "Slay Zao'cho.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32713] = { id = 32713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocks Fall, People Die", description = "Words fail to describe the massive horror of rock, bone, and blood that rumbles mindlessly and aimlessly ahead of you.\n\nMassive earthquakes crack the seemingly hollow shell of ground beneath the figure, leaving destruction in its wake. It appears that the creature is unaware of your presence.", objectives = "Slay the Rocky Horror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32714] = { id = 32714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Tempest", description = "You hear a fierce and militant voice roaring in the distance. A crackling storm swells and swirls around a clouded, shadowy figure. Lightning flashes and No'ku Stormsayer appears, his scornful gaze aimed directly at you.", objectives = "Slay No'ku Stormsayer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32715] = { id = 32715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requiem for a Queen", description = "A chilling breeze sweeps across your body, bringing with it a haunting drape of sadness. Your soul sinks as you hear the faint, melodic cries of Monara, the last Queen of the Mogu.\n\nHer sweet requiem creeps through the air, bending and shaping itself into a spectral hand, reaching for your heart. As it grabs hold, you see a brief flash of Monara's last moments... her brutal murder by the hand of Lei Shen.\n\nSong turns to sadness and Monara weeps, wailing louder and louder into the darkness.", objectives = "Put Monara to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32716] = { id = 32716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Thunder King", description = "As the fog dissipates from the fallen sentries, you feel a sudden rumbling.\n\nThe rocks blocking the sewer tunnels tumble forward and crash into the outflow tanks below, as four putrid eyes lunge from the darkness.", objectives = "Defeat the ambush!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32717] = { id = 32717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[32718] = { id = 32718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Runes of Fate", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate, valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", objectives = "Collect 50 Lesser Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32719] = { id = 32719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Runes of Fate", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate, valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", objectives = "Collect 50 Lesser Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32720] = { id = 32720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose Your Assignment", objectives = "Kill 10 Kirin Tor units or players on the Isle of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
