quests[32758] = { id = 32758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reader for the Dead Tongue", description = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", objectives = "Bring the codex to a Warlock trainer in your capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32783] = { id = 32783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ga'nar's Vengeance", description = "My brother's head is as thick as his axe and he is as stubborn as a gronn.\n\nWhen Ga'nar left he took with him some of the finest warriors in the clan and headed north to the Daggermaw Ravine. If they are still out there, you must find them. Ga'nar will not listen to me.\n\nHelp him see his vengeance through if you must but please bring him back to us.", completion = "So my brother would not dare come himself?", objectives = "Find Ga'nar near Daggermaw Ravine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32784] = { id = 32784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Trail of Blood", description = "This orc appears to have made a last stand, dying while defending his fallen wolf. His clothes are that of the Frostwolf Clan.\n\nFrom the tracks and other signs it would appear there were six other wolves during the battle that got away, one bleeding. A trail of fresh blood leads off into the desert northward.", objectives = "Follow the trail of blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32791] = { id = 32791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Hunt Begin!", description = "I have no time for my brother's whimpering. We hunt for vengeance or death.\n\nThe Thunderlord chieftain slew my father and left me for dead, so I shall take his three sons, the first of which is this runt in my hand.\n\nThis filth has revealed the number and positions of the Thunderlords in the ravine beyond.\n\nJoin us, if you dare, and you will witness how real warriors of the Frostwolf clan fight. Get in my way, and I will end you.", completion = "The Thunderlord think their numbers will save them.\n\nWe will show them that their numbers count for nothing when hunted by a pack of Frostwolves.", objectives = "Confront Grotan the Herald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
